// Localizer is the application-facing wrapper around go-i18n. Keeping the
// message lookup here makes CLI and native UI use the same embedded catalogs.
type Localizer struct {
	protocol  bool
	language  Language
	localizer *goi18n.Localizer
}

func NewLocalizer(language Language) *Localizer {
	if language != English && language != Chinese {
		panic("invalid localizer language: " + string(language))
	}
	return &Localizer{language: language, localizer: goi18n.NewLocalizer(messageBundle(), string(language))}
}

// Count formats the whole phrase, so the count need not precede the noun.
func (l *Localizer) Count(id string, n int) string {
	form := ".other"
	if n == 1 {
		form = ".one"
	}
	return fmt.Sprintf(l.Text(id+form, nil), n)
}

// Label formats only application-owned status values, never paths, notes or error details.
func (l *Localizer) Label(value string) string {
	if l.language == English {
		return value
	}
	key := "cli.label." + strings.ReplaceAll(strings.ReplaceAll(strings.ToLower(value), " ", "_"), "-", "_")
	if _, ok := defaultMessages[key]; ok {
		return l.Text(key, nil)
	}
	return value
}

func (l *Localizer) Language() Language { return l.language }

func (l *Localizer) Text(id string, data any) string {
	if l.protocol {
		if text, ok := diagnosticJSON[id]; ok {
			return text
		}
	}
	defaultMessage, ok := defaultMessages[id]
	if !ok {
		panic("missing default message: " + id)
	}
	config := &goi18n.LocalizeConfig{DefaultMessage: defaultMessage, TemplateData: data}
	text, err := l.localizer.Localize(config)
	if errors.As(err, new(*goi18n.MessageNotFoundErr)) {
		return goi18n.NewLocalizer(messageBundle(), string(English)).MustLocalize(config)
	}
	if err != nil {
		panic(err)
	}
	return text
}
